import java.nio.file.*;import java.util.*;import javax.tools.*;import javax.lang.model.element.*;import javax.lang.model.type.*;import com.sun.source.tree.*;import com.sun.source.util.*;
/** Full-source native method attribution; original mode only records syntax/provenance. */
public class GrowthScanner {
 static String q(Object s){return "\""+String.valueOf(s).replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r").replace("\t","\\t")+"\"";}
 public static void main(String[] a)throws Exception{
  boolean original=a.length>2&&a[2].equals("original");JavaCompiler c=ToolProvider.getSystemJavaCompiler();DiagnosticCollector<JavaFileObject>d=new DiagnosticCollector<>();StandardJavaFileManager f=c.getStandardFileManager(d,null,null);
  JavacTask t=(JavacTask)c.getTask(null,f,d,Arrays.asList("-proc:none","-source","8","-classpath",new String(Files.readAllBytes(Paths.get(a[1]))).trim(),"-Xmaxerrs","100000"),null,f.getJavaFileObjectsFromStrings(Files.readAllLines(Paths.get(a[0]))));Trees tr=Trees.instance(t);List<CompilationUnitTree>us=new ArrayList<>();for(CompilationUnitTree u:t.parse())us.add(u);if(!original)t.analyze();
  final List<String> overrides=new ArrayList<>();
  if(!original){final TypeElement box=t.getElements().getTypeElement("net.minecraft.util.math.AxisAlignedBB");for(CompilationUnitTree u:us)new TreePathScanner<Void,Void>(){public Void visitMethod(MethodTree m,Void v){Element e=tr.getElement(getCurrentPath());if(e instanceof ExecutableElement&&(m.getName().contentEquals("expand")||m.getName().contentEquals("grow"))&&e.getEnclosingElement() instanceof TypeElement&&!e.getEnclosingElement().equals(box)&&t.getTypes().isSubtype(e.getEnclosingElement().asType(),box.asType())){List<? extends VariableElement> ps=((ExecutableElement)e).getParameters();if(ps.size()==3&&ps.get(0).asType().getKind()==TypeKind.DOUBLE&&ps.get(1).asType().getKind()==TypeKind.DOUBLE&&ps.get(2).asType().getKind()==TypeKind.DOUBLE)overrides.add(e.toString());}return super.visitMethod(m,v);}}.scan(u,null);}
  for(CompilationUnitTree u:us){String src=u.getSourceFile().getCharContent(true).toString();new TreePathScanner<Void,Void>(){
   TreePath p(Tree n){return TreePath.getPath(u,n);}String txt(Tree n){return src.substring((int)tr.getSourcePositions().getStartPosition(u,n),(int)tr.getSourcePositions().getEndPosition(u,n));}
   Double literal(ExpressionTree n){if(n instanceof ParenthesizedTree)return literal(((ParenthesizedTree)n).getExpression());if(n instanceof LiteralTree){Object v=((LiteralTree)n).getValue();return v instanceof Number?((Number)v).doubleValue():null;}if(n.getKind()==Tree.Kind.UNARY_MINUS||n.getKind()==Tree.Kind.UNARY_PLUS){Double v=literal(((UnaryTree)n).getExpression());return v==null?null:n.getKind()==Tree.Kind.UNARY_MINUS?-v:v;}return null;}
   public Void visitMethodInvocation(MethodInvocationTree n,Void v){if(n.getMethodSelect() instanceof MemberSelectTree){MemberSelectTree s=(MemberSelectTree)n.getMethodSelect();String name=s.getIdentifier().toString();if(name.equals("expand")||name.equals("grow")){
    Element e=original?null:tr.getElement(getCurrentPath());TypeMirror receiver=original?null:tr.getTypeMirror(p(s.getExpression()));boolean nativeOwner=e instanceof ExecutableElement&&e.getEnclosingElement().toString().equals("net.minecraft.util.math.AxisAlignedBB")&&receiver!=null&&receiver.toString().equals("net.minecraft.util.math.AxisAlignedBB");
    boolean good=nativeOwner&&n.getArguments().size()==3&&overrides.isEmpty();List<String>args=new ArrayList<>(),values=new ArrayList<>(),types=new ArrayList<>();for(ExpressionTree arg:n.getArguments()){Double val=literal(arg);good&=val!=null&&Double.isFinite(val)&&val>=0&&Double.doubleToRawLongBits(val)!=0x8000000000000000L;args.add(q(txt(arg)));values.add(val==null?"null":q(Double.toString(val)));TypeMirror ty=original?null:tr.getTypeMirror(p(arg));types.add(q(ty));}
    String method="";List<String>owners=new ArrayList<>();for(TreePath p=getCurrentPath();p!=null;p=p.getParentPath()){if(p.getLeaf() instanceof MethodTree&&method.isEmpty())method=((MethodTree)p.getLeaf()).getName().toString();if(p.getLeaf() instanceof ClassTree)owners.add(((ClassTree)p.getLeaf()).getSimpleName().toString());}Collections.reverse(owners);
    long start=tr.getSourcePositions().getStartPosition(u,n),end=tr.getSourcePositions().getEndPosition(u,n),selEnd=tr.getSourcePositions().getEndPosition(u,s);
    System.out.println("{\"path\":"+q(Paths.get(u.getSourceFile().toUri()))+",\"start\":"+start+",\"end\":"+end+",\"nameStart\":"+(selEnd-name.length())+",\"nameEnd\":"+selEnd+",\"name\":"+q(name)+",\"method\":"+q(method)+",\"classes\":"+q(String.join(".",owners))+",\"receiver\":"+q(txt(s.getExpression()))+",\"receiverType\":"+q(receiver)+",\"owner\":"+q(e==null?null:e.getEnclosingElement())+",\"signature\":"+q(e==null?null:e.asType())+",\"native\":"+nativeOwner+",\"candidate\":"+good+",\"arguments\":["+String.join(",",args)+"],\"values\":["+String.join(",",values)+"],\"types\":["+String.join(",",types)+"]}");
   }}return super.visitMethodInvocation(n,v);}
  }.scan(u,null);}
  System.err.println((original?"Original syntax provenance":"Native attribution only")+"; inputs="+us.size()+"; source AABB overrides="+overrides.size()+"; errors="+d.getDiagnostics().stream().filter(x->x.getKind()==Diagnostic.Kind.ERROR).count());f.close();
 }
}
